update public.learning_paths
set
  title = 'Anthropological Theory',
  goal = 'Anthropological Theory',
  summary = 'This course surveys the major theoretical traditions, disputes, and contemporary turns that have shaped anthropology as a discipline. Students read classic and contemporary theory alongside ethnographic cases, learning how concepts such as culture, structure, function, symbol, practice, habitus, discourse, materiality, ontology, race, gender, coloniality, and more-than-human relations become tools for explanation. The course sequence expands into a granular, research-ready syllabus that emphasizes critique, application, and theory-building.',
  data = $anthjson${"slug": "anthropological-theory", "title": "Anthropological Theory", "description": "This course surveys the major theoretical traditions, disputes, and contemporary turns that have shaped anthropology as a discipline. Students read classic and contemporary theory alongside ethnographic cases, learning how concepts such as culture, structure, function, symbol, practice, habitus, discourse, materiality, ontology, race, gender, coloniality, and more-than-human relations become tools for explanation. The course sequence expands into a granular, research-ready syllabus that emphasizes critique, application, and theory-building.", "topics": [{"id": "1d2992c9-0e41-47f1-a9d7-e841daf78114", "type": "topic", "title": "What Theory Does in Anthropology", "description": "Introduces theory as a toolkit for asking better questions about culture, power, history, meaning, material life, embodiment, and human difference.", "children": [{"id": "49b54260-4f9d-4c1c-b4df-b0a02fb3334b", "type": "subtopic", "title": "Theory, concept, and ethnographic problem", "children": [{"id": "f5c68d25-6b5d-4c13-b90d-9d2aa98892ea", "type": "concept", "title": "Concept"}, {"id": "8791720b-cfed-4bb4-b08c-98a46623f4ad", "type": "concept", "title": "Analytic frame"}, {"id": "dc58c191-a854-4bfb-82f0-3c5bc8e0f2c0", "type": "concept", "title": "Problematic"}, {"id": "1aeeee36-2e4b-405c-8262-f830b5afbc59", "type": "concept", "title": "Ethnographic case"}, {"id": "e93df49d-2c8a-4abc-a6ae-6abefbae3112", "type": "concept", "title": "Comparison"}, {"id": "eed10490-6e1b-4d1f-bbe9-2d7ef1882020", "type": "concept", "title": "Scale"}], "description": "Students learn that theory is not decoration; it defines what counts as a problem, what evidence matters, and what explanation looks like."}, {"id": "dec7f6cb-0b28-4c53-ae74-da87d80c7e13", "type": "subtopic", "title": "Four-field and subfield relationships", "children": [{"id": "c705d51e-551c-453a-bbd8-feeed5e086ba", "type": "concept", "title": "Cultural anthropology"}, {"id": "9a3403c4-999e-4b18-98f8-951c4bf38168", "type": "concept", "title": "Biological anthropology"}, {"id": "f3990041-800f-4ee7-8b53-999c44347fea", "type": "concept", "title": "Archaeology"}, {"id": "30492bf4-5c5a-4549-ba07-ba4d2693d7a9", "type": "concept", "title": "Linguistic anthropology"}, {"id": "361868ea-b76c-4519-b86a-d2a88dfa4113", "type": "concept", "title": "Holism"}, {"id": "17fc0dcd-abf6-4bd9-a5ac-3f3d2a796aa7", "type": "concept", "title": "Interdisciplinarity"}], "description": "This subtopic shows how cultural, biological, archaeological, and linguistic anthropology have different evidence but shared theoretical concerns."}, {"id": "b086b2ac-4190-4ce9-8c79-fe23cba23372", "type": "subtopic", "title": "Theory and the politics of knowledge", "children": [{"id": "489d0a89-190f-45e3-824a-b10ce86b979f", "type": "concept", "title": "Epistemology"}, {"id": "0fc05bd8-7d78-457c-95b6-56363d09dbe5", "type": "concept", "title": "Positionality"}, {"id": "18ec3e43-e57d-4560-815f-ea1baa0b888d", "type": "concept", "title": "Canon formation"}, {"id": "5de55aff-560e-4a5f-a10f-9d6424053377", "type": "concept", "title": "Knowledge production"}, {"id": "6a2fe460-d942-4455-9495-1fc5e3c90844", "type": "concept", "title": "Authority"}, {"id": "723077f4-1102-4786-b05c-92f9cb509703", "type": "concept", "title": "Public anthropology"}], "description": "Students examine how anthropological knowledge has been shaped by colonial power, race, class, gender, funding, institutions, and publics."}]}, {"id": "9f1b4b66-1c29-4b23-a344-e61270304aad", "type": "topic", "title": "Evolutionism and Early Comparative Thought", "description": "Studies nineteenth-century theories that ranked societies along developmental stages and explains why later anthropology rejected their assumptions.", "children": [{"id": "704a908e-d4ea-4a87-b580-4dcd239979ad", "type": "subtopic", "title": "Unilineal evolutionism", "children": [{"id": "91b81b6b-1fae-4b82-b296-700b563e63aa", "type": "concept", "title": "Savagery/barbarism/civilization"}, {"id": "4db68866-e5d0-4a99-bb97-6c94c82ff127", "type": "concept", "title": "Survivals"}, {"id": "2015850a-347d-4f08-8a03-16741635fcc0", "type": "concept", "title": "Progress narratives"}, {"id": "f0335e03-84a7-4abe-bb24-54adace34245", "type": "concept", "title": "Ethnocentrism"}, {"id": "c6a49ef5-c373-43b6-bfe3-08c496725579", "type": "concept", "title": "Armchair anthropology"}], "description": "The point is to understand early anthropology's comparative ambition and its deeply flawed hierarchy of social progress."}, {"id": "ea1aa1d2-4b30-4412-ad7e-46aff8c2d24e", "type": "subtopic", "title": "Comparative method and classification", "children": [{"id": "9aeca538-8e1a-41a1-a9ed-05ca0d1b9097", "type": "concept", "title": "Typology"}, {"id": "b50e2b1a-9b90-4bec-b7ae-fc50b4698907", "type": "concept", "title": "Comparative tables"}, {"id": "e22cbc10-5759-47bf-af38-b4fe9d33366b", "type": "concept", "title": "Diffusion"}, {"id": "54d7fee5-87d0-4afc-b07d-a783b13e9ef6", "type": "concept", "title": "Culture areas"}, {"id": "afc17a23-6a9e-4616-b812-22ff66c9fe3a", "type": "concept", "title": "Speculative history"}, {"id": "c95195e0-0ea8-49a2-a6e0-1edbc141d7b0", "type": "concept", "title": "Social evolution"}], "description": "Students learn how early theorists used cross-cultural data and why those comparisons often ignored history, context, and power."}, {"id": "93381697-616d-4169-ab57-fc266c1adb50", "type": "subtopic", "title": "Legacy and critique", "children": [{"id": "70ad9c35-722f-4fe1-a975-468196003d3d", "type": "concept", "title": "Scientific racism"}, {"id": "74f93ad8-c666-4a76-8a8a-fbb999f6ffd3", "type": "concept", "title": "Colonial knowledge"}, {"id": "7abe7918-6307-41a5-b9ce-620c226dad9f", "type": "concept", "title": "Museum collecting"}, {"id": "97eb39ba-07ff-4489-aa87-e30cda07647d", "type": "concept", "title": "Cultural hierarchy"}, {"id": "8302fcd4-3697-46b9-9885-e6e026472921", "type": "concept", "title": "Degeneration theories"}, {"id": "d2e5fd3d-4900-4f70-b8f0-c3bcc15448c1", "type": "concept", "title": "Modern evolutionary anthropology"}], "description": "This subtopic connects early theory to later debates about race science, colonialism, museums, and evolutionary explanation."}]}, {"id": "28bc8254-e221-48b4-9092-a159e5f8b76c", "type": "topic", "title": "Boas, Historical Particularism, and Cultural Relativism", "description": "Explores Boasian anthropology as a decisive critique of racial determinism, grand evolutionism, and decontextualized comparison.", "children": [{"id": "0071e879-3cee-4d0b-a5c0-de0c77f59433", "type": "subtopic", "title": "Historical particularism", "children": [{"id": "acf1404f-084d-4b8e-ae8a-28848d619b62", "type": "concept", "title": "Diffusion"}, {"id": "63d69bf6-4158-40c9-8c63-533b255bdd7f", "type": "concept", "title": "Cultural history"}, {"id": "0f80aeca-df2d-42e1-b307-c4b421efd394", "type": "concept", "title": "Particularism"}, {"id": "67ffe1e2-d893-4134-b31d-d6d353fba27d", "type": "concept", "title": "Context"}, {"id": "6d178b73-bd2e-4c2f-8f8b-19dac82d8198", "type": "concept", "title": "Contingency"}, {"id": "9d0d99ac-1da1-411c-840e-8a28a1fcf3ee", "type": "concept", "title": "Anti-evolutionism"}], "description": "Students learn to interpret cultural forms through specific histories rather than universal stages."}, {"id": "bd0eb447-67a0-4581-9cb1-accd2a338d3f", "type": "subtopic", "title": "Cultural relativism", "children": [{"id": "fbcab572-dcd5-4ed8-a8f9-eca4757f6692", "type": "concept", "title": "Ethnocentrism"}, {"id": "249262b9-d406-4c3c-be7b-d667a5826ac5", "type": "concept", "title": "Methodological relativism"}, {"id": "cee5b720-ddc4-4317-894f-93275ebad5a9", "type": "concept", "title": "Moral judgment"}, {"id": "4e89e37f-a17e-4bd0-92d2-2f476d441876", "type": "concept", "title": "Translation"}, {"id": "8919b354-50be-49c9-b9d0-ce83693759ec", "type": "concept", "title": "Cultural critique"}, {"id": "5288eb4a-9ac1-4457-80ac-dcc5570aaa02", "type": "concept", "title": "Human rights debate"}], "description": "This subtopic distinguishes methodological relativism from moral relativism and shows why the distinction matters."}, {"id": "37503b73-e2c7-4988-ad0e-91eb3dcb24b0", "type": "subtopic", "title": "Boasian legacies", "children": [{"id": "ce06e273-4b79-45e2-9060-aeee31b763b3", "type": "concept", "title": "Race critique"}, {"id": "d5e764e4-a9f8-4c75-9353-4ee671cb4144", "type": "concept", "title": "Sapir"}, {"id": "b64924d3-29c4-4f01-9da9-9f2a7528f018", "type": "concept", "title": "Benedict"}, {"id": "892fd48e-a321-4149-aaab-d127db5a37c0", "type": "concept", "title": "Mead"}, {"id": "5681a34d-024a-4016-9e42-020a804aaeb8", "type": "concept", "title": "Culture and personality"}, {"id": "0fb4e33f-3fe8-47ba-9dc5-4e8200e748d1", "type": "concept", "title": "Language documentation"}], "description": "Students trace Boas's influence on race critique, salvage anthropology, linguistics, folklore, and American cultural anthropology."}]}, {"id": "2adb5347-670c-4558-8f17-67e74649b7c8", "type": "topic", "title": "Functionalism and Structural Functionalism", "description": "Examines theories that explain institutions by their roles in satisfying needs, maintaining order, regulating conflict, and reproducing social structure.", "children": [{"id": "32bf0804-6cd1-47c5-97ef-855103740897", "type": "subtopic", "title": "Malinowski and functionalism", "children": [{"id": "3da93e4f-196e-4042-bffa-df70af81cd91", "type": "concept", "title": "Participant observation"}, {"id": "cfd89e88-626c-4fa1-8035-8024d0631af7", "type": "concept", "title": "Needs theory"}, {"id": "a9ec0cc8-f675-4a6d-8830-5e2a0fa0feb9", "type": "concept", "title": "Institution"}, {"id": "b53b0b97-87f9-4062-9b48-6df5e9574fa3", "type": "concept", "title": "Trobriand Islands"}, {"id": "e2ff5ce0-f5d6-49d5-85be-71e3d1826676", "type": "concept", "title": "Kula exchange"}, {"id": "555a6345-7a0d-4df4-844c-26dc384d89d9", "type": "concept", "title": "Ethnographic present"}], "description": "Students learn how intensive fieldwork and the concept of function changed the discipline's method and theory."}, {"id": "3ad61422-cab5-4ff6-a919-db6e205984c0", "type": "subtopic", "title": "Radcliffe-Brown and social structure", "children": [{"id": "e22c9473-bd14-4f63-adf9-9ae1c0ad212f", "type": "concept", "title": "Social structure"}, {"id": "60f5e10a-adbc-44aa-a021-1c6e29ddc13e", "type": "concept", "title": "Social function"}, {"id": "1eead2b9-a652-4ae3-9604-5eb72eca4676", "type": "concept", "title": "Jural rules"}, {"id": "d1aa2bda-be24-4454-8706-7abd86ca1ff5", "type": "concept", "title": "Descent"}, {"id": "14a91f4d-f6ed-422a-b3ef-35fd84225e5e", "type": "concept", "title": "Equilibrium"}, {"id": "d4109d54-9b1b-48a6-b466-d2aba0c37192", "type": "concept", "title": "Comparative sociology"}], "description": "This subtopic emphasizes relations, roles, norms, and institutions as parts of a social system."}, {"id": "42c22930-1e0f-4f34-aabd-c5b9b417c7d0", "type": "subtopic", "title": "Critiques of functionalism", "children": [{"id": "25cc09c8-3c70-44cb-aca9-b43cdb263c60", "type": "concept", "title": "Ahistoricism"}, {"id": "052678b2-5769-4caa-959d-f84defb5c79a", "type": "concept", "title": "Conflict"}, {"id": "07c7fbd1-531d-48e5-8a45-e297aa7f4301", "type": "concept", "title": "Change"}, {"id": "6c1691cf-0ecd-4452-b87e-6db26e7ac8d6", "type": "concept", "title": "Colonial context"}, {"id": "28e4ebca-f9b5-4175-a963-c5575172b1db", "type": "concept", "title": "Teleology"}, {"id": "2feb758c-8da5-476d-a715-9e958aa6f5af", "type": "concept", "title": "Over-integration"}], "description": "Students identify the limits of explaining institutions as stable, integrated, and consensual."}]}, {"id": "61d1dbdf-222d-4fd6-933d-3eb82891eab6", "type": "topic", "title": "Structuralism, Symbolic Anthropology, and Meaning", "description": "Develops tools for interpreting symbols, myths, rituals, classifications, and cultural systems of meaning.", "children": [{"id": "89e0d0e6-e4ca-46a5-92f5-839dc18b2cfc", "type": "subtopic", "title": "Levi-Strauss and structuralism", "children": [{"id": "467b3a15-6525-4108-a705-617ee4f97396", "type": "concept", "title": "Binary opposition"}, {"id": "e88c8228-5c87-4ebe-8bd2-bcd7255a0cff", "type": "concept", "title": "Mytheme"}, {"id": "a0537e96-6bdd-40b0-9678-848839b9a1b7", "type": "concept", "title": "Transformation"}, {"id": "523ebe65-52a7-4282-81c2-a19d9f064f53", "type": "concept", "title": "Bricolage"}, {"id": "86b3efbc-3098-421b-b044-28d543f7046b", "type": "concept", "title": "Culinary triangle"}, {"id": "63aa7b12-a1eb-47dd-b643-98ff3df424ac", "type": "concept", "title": "Deep structure"}], "description": "Students learn how structuralists looked for underlying binary oppositions and transformations in myth, kinship, and classification."}, {"id": "319de546-1f6f-439d-9e37-f51f568d60dc", "type": "subtopic", "title": "Geertz and interpretive anthropology", "children": [{"id": "ec608eab-48ed-4f3d-8b40-9772130d6385", "type": "concept", "title": "Thick description"}, {"id": "25a93fe2-8625-4aad-9ae0-987d9da57d08", "type": "concept", "title": "Semiotic concept of culture"}, {"id": "f70ceec7-ed31-489c-b357-a06b771fd5c8", "type": "concept", "title": "Balinese cockfight"}, {"id": "3babc367-d285-4239-9601-184159e3bfb3", "type": "concept", "title": "Local knowledge"}, {"id": "eb831ee3-91c3-459e-a9d8-4c6986a024e6", "type": "concept", "title": "Interpretation"}, {"id": "c04362c1-df1d-4def-8aec-9f51795595fe", "type": "concept", "title": "Meaning"}], "description": "This subtopic teaches culture as webs of significance and ethnography as thick description."}, {"id": "4fce98d9-5e87-45b9-8a20-0307ef57a451", "type": "subtopic", "title": "Symbol, ritual, and performance", "children": [{"id": "c7b06405-ec59-4816-a1a7-cdcee4ecf4c5", "type": "concept", "title": "Victor Turner"}, {"id": "db69f326-e367-4fcc-b96b-b4384c92e204", "type": "concept", "title": "Liminality"}, {"id": "449e92a3-2579-4c1a-aeff-6e88640aa26d", "type": "concept", "title": "Communitas"}, {"id": "0592a325-0fef-4415-9ce9-9d26492362c4", "type": "concept", "title": "Condensation symbol"}, {"id": "0b4ac13c-11e8-4a86-84bf-84c2091a70aa", "type": "concept", "title": "Social drama"}, {"id": "a1be2355-ba4d-416b-ac13-6cfb1212eab5", "type": "concept", "title": "Performance"}], "description": "Students analyze how symbols condense social meanings and how rituals dramatize order, conflict, and transformation."}]}, {"id": "0d50255d-7b5a-46f9-9b1a-d4a33f56b8fa", "type": "topic", "title": "Marxist, Political Economy, and World-Systems Approaches", "description": "Connects culture to labor, capitalism, colonialism, class, dependency, extraction, and global inequality.", "children": [{"id": "77e71d76-729a-4776-8d2d-af0672663dd6", "type": "subtopic", "title": "Materialism and mode of production", "children": [{"id": "b84fe00c-5554-4b2f-840a-90ca271b1585", "type": "concept", "title": "Mode of production"}, {"id": "f4395608-ae54-4f7c-a037-e81c07abad01", "type": "concept", "title": "Base/superstructure"}, {"id": "3a37bd54-51f8-45f2-b40c-a660b6929dd4", "type": "concept", "title": "Labor"}, {"id": "1e437c71-3ced-4b3b-b83c-51d9ec91380e", "type": "concept", "title": "Surplus"}, {"id": "70e3d4fb-ff93-4f97-9445-637d30d21f2e", "type": "concept", "title": "Class"}, {"id": "1374ffee-8cb5-470c-953e-fd4220d77b85", "type": "concept", "title": "Ideology"}], "description": "Students learn how economic organization shapes social relations without reducing culture to economics."}, {"id": "31a7ee95-c1c5-4f99-b0e0-22da83a5ae46", "type": "subtopic", "title": "Political economy in anthropology", "children": [{"id": "7c8356ac-c2ca-4a78-ab8b-7db21d4656d0", "type": "concept", "title": "Eric Wolf"}, {"id": "4afede03-2a19-49f9-8283-4703be4f6ad3", "type": "concept", "title": "Dependency"}, {"id": "4dd1feda-98eb-4053-b4a8-d9c8acc21611", "type": "concept", "title": "Articulation"}, {"id": "1efdc5ea-f0fa-409f-8750-f9402335c548", "type": "concept", "title": "Commodity chains"}, {"id": "85e01998-06ae-42f4-8739-3833b96d867f", "type": "concept", "title": "Peasant studies"}, {"id": "0d6aa183-38ad-42e5-ade6-214029b895a3", "type": "concept", "title": "Labor migration"}], "description": "This subtopic links local ethnographic life to colonialism, markets, states, and global capital."}, {"id": "ee70c2ab-0625-4dd9-b07a-7e3d55e81bfa", "type": "subtopic", "title": "World-systems and globalization", "children": [{"id": "4670c280-43ea-4bba-92e8-1f98017256b9", "type": "concept", "title": "World-system"}, {"id": "cfe83312-e891-463b-8732-c29548e1dc56", "type": "concept", "title": "Core/periphery"}, {"id": "513d27b4-1abe-464d-93ac-21bffea30dda", "type": "concept", "title": "Unequal exchange"}, {"id": "a9f28b04-003b-4eb4-9c23-742e7273d065", "type": "concept", "title": "Plantations"}, {"id": "d3929c9c-e85a-4420-b558-c9e8832e50b9", "type": "concept", "title": "Extraction"}, {"id": "01b8aba2-78ff-4959-a76e-a2e3b3bd31fc", "type": "concept", "title": "Neoliberal restructuring"}], "description": "Students learn to think across core, periphery, commodity flow, and historical capitalism."}]}, {"id": "d63f7d3c-824b-4cd6-852f-cf12cd6e01e8", "type": "topic", "title": "Practice Theory, Agency, and Social Reproduction", "description": "Explains how people reproduce social structures through everyday action while also improvising, resisting, and transforming them.", "children": [{"id": "a66ff6b8-0f64-42cc-9427-d5d0d1014300", "type": "subtopic", "title": "Bourdieu: habitus, field, and capital", "children": [{"id": "3fb39e9b-e49a-4922-8927-b6efdcd3fe44", "type": "concept", "title": "Habitus"}, {"id": "68ddb9ed-5608-4630-9a83-8f32824e5906", "type": "concept", "title": "Field"}, {"id": "ff77a3c2-d38d-4e95-bba7-7eac348fb575", "type": "concept", "title": "Cultural capital"}, {"id": "d3f3dbc3-47e9-4c4c-9ae9-dacdc43f0549", "type": "concept", "title": "Social capital"}, {"id": "359c1794-52a2-40f5-b394-9724e104b119", "type": "concept", "title": "Symbolic capital"}, {"id": "b5f236f3-5d94-468c-808d-6128722bf914", "type": "concept", "title": "Doxa"}], "description": "Students learn how embodied dispositions and unequal resources shape action without making people simple rule-followers."}, {"id": "de76e900-2b8b-4841-a2da-b7058fe38af0", "type": "subtopic", "title": "Giddens and structuration", "children": [{"id": "d06c17d0-67d1-4ec3-8b61-874e60130f93", "type": "concept", "title": "Duality of structure"}, {"id": "ce73dd3c-5765-49fe-983a-eb35aa3f8105", "type": "concept", "title": "Agency"}, {"id": "4ad59855-2efb-4ec7-9669-236878161050", "type": "concept", "title": "Rules and resources"}, {"id": "98e53cbc-128f-4eb1-be7c-d595010ee318", "type": "concept", "title": "Reflexivity"}, {"id": "d44f5f8b-0ce6-4c4c-818c-1176d76119d5", "type": "concept", "title": "Routine"}, {"id": "70836481-f98a-4a4e-80d4-fd832cebfc3d", "type": "concept", "title": "Institutional reproduction"}], "description": "This subtopic clarifies the relation between structure and agency as an ongoing process."}, {"id": "9dc60218-bb48-4804-b17f-06f45b36c8ef", "type": "subtopic", "title": "Resistance, accommodation, and tactics", "children": [{"id": "8eda55b0-ddab-498b-ad13-aeb5638875b1", "type": "concept", "title": "Everyday resistance"}, {"id": "dc36666d-97a8-404c-a9ef-604300c41f36", "type": "concept", "title": "Hidden transcript"}, {"id": "23132654-58fa-46a0-920c-21eb1c7a4dfb", "type": "concept", "title": "Tactics"}, {"id": "c70a01bb-d869-4b84-9e34-c55158bba6a6", "type": "concept", "title": "Accommodation"}, {"id": "1542fa66-af46-493d-bffd-87bd3fab1a5c", "type": "concept", "title": "Improvisation"}, {"id": "ef303f43-06fe-4a97-b5dc-4b86ce210218", "type": "concept", "title": "Counter-conduct"}], "description": "Students examine how domination is negotiated through everyday practices, hidden transcripts, and small acts."}]}, {"id": "a4b2ba18-6265-46a8-a5d0-23c4536d8acd", "type": "topic", "title": "Feminist, Gender, and Queer Anthropology", "description": "Centers gender, sexuality, kinship, reproduction, embodiment, labor, and the critique of male-centered theory.", "children": [{"id": "80546f81-1e44-4d18-ab2c-eba3275e6ad0", "type": "subtopic", "title": "Feminist critiques of the canon", "children": [{"id": "345cc66d-150d-411a-9e97-ab18a224b1f9", "type": "concept", "title": "Androcentrism"}, {"id": "43e90d40-672c-48f3-a7d3-87d37376736a", "type": "concept", "title": "Public/private"}, {"id": "ab3176cf-d225-44c2-9fa2-f1228ecb233a", "type": "concept", "title": "Domestic labor"}, {"id": "f1c04925-cf11-4955-bac9-80a58661fe14", "type": "concept", "title": "Reproduction"}, {"id": "76cebe39-9550-4ef8-bb36-340ad0da86a6", "type": "concept", "title": "Standpoint"}, {"id": "8b4b1fd0-801c-470c-9308-e60604355913", "type": "concept", "title": "Embodiment"}], "description": "Students learn how feminist anthropology challenged assumptions about universality, public/private divides, and ethnographic authority."}, {"id": "488cee57-818f-4fbd-b27e-e5cd7dab1497", "type": "subtopic", "title": "Gender as social relation and performance", "children": [{"id": "9f399d86-4b06-43d3-b78e-6d0f81e57b85", "type": "concept", "title": "Gender roles"}, {"id": "6d8207cd-1a22-43db-8194-122495320e33", "type": "concept", "title": "Performativity"}, {"id": "59c6a384-794b-4ff9-8267-cee6a22d1915", "type": "concept", "title": "Masculinity"}, {"id": "063e4a7f-22af-4b8c-8467-3790418e16e2", "type": "concept", "title": "Femininity"}, {"id": "9fed85c5-09ed-4fbf-85e2-0155c41501f1", "type": "concept", "title": "Third gender"}, {"id": "7cd8a2f1-4915-45fa-877a-70a6ed334b27", "type": "concept", "title": "Intersectionality"}], "description": "This subtopic treats gender as structured, enacted, contested, and historically variable."}, {"id": "b4572e0e-b254-49b3-ac5d-1fd3f3a739d8", "type": "subtopic", "title": "Queer anthropology", "children": [{"id": "a4ea8f7c-1def-456b-a7b3-70ca9f3adba1", "type": "concept", "title": "Heteronormativity"}, {"id": "9f5b1a4f-bac5-431f-842e-950e90a7f7e0", "type": "concept", "title": "Queer kinship"}, {"id": "01725fd7-6e2a-452a-9bb7-e776f6368c00", "type": "concept", "title": "Sexual citizenship"}, {"id": "fba4086b-a829-4e98-a57e-d58c406fa335", "type": "concept", "title": "Desire"}, {"id": "4e19f8cc-840a-44bc-b2e1-3ed79b0ebe74", "type": "concept", "title": "Trans studies"}, {"id": "0f4af3be-823a-49b1-8a56-4d45b2cb1421", "type": "concept", "title": "Intimacy"}], "description": "Students analyze sexuality, kinship, normativity, desire, identity, and state regulation across contexts."}]}, {"id": "2cc15c3f-a88e-43cc-b926-f450dbb8e159", "type": "topic", "title": "Postcolonial, Decolonial, Race, and Indigenous Critiques", "description": "Interrogates anthropology's entanglement with empire and develops approaches accountable to colonial histories, racial formation, and Indigenous sovereignty.", "children": [{"id": "5a4ea01f-de94-4bb7-98b9-6ea7e2795896", "type": "subtopic", "title": "Colonialism and anthropological knowledge", "children": [{"id": "e3b67b8f-bde6-44fb-8668-bf268d577ad6", "type": "concept", "title": "Colonial encounter"}, {"id": "43116449-fd20-4293-b1ea-0d831e54a145", "type": "concept", "title": "Native informant"}, {"id": "04bee470-5212-4cf0-8b16-41f30ca4d947", "type": "concept", "title": "Salvage anthropology"}, {"id": "2abff98d-e49a-4fc2-9e21-5789687ae9c4", "type": "concept", "title": "Archive"}, {"id": "91705a57-e297-41ec-b1f8-503be93fbf33", "type": "concept", "title": "Museum"}, {"id": "5f93a061-c6ef-4112-ace3-d122338488f9", "type": "concept", "title": "Extractive research"}], "description": "Students learn how fieldwork, museums, archives, and categories were shaped by imperial power."}, {"id": "f221afaf-6f3c-4136-bc49-3955c3adcde0", "type": "subtopic", "title": "Postcolonial theory", "children": [{"id": "e7bb01e1-94a5-4363-a391-a24a550e3b50", "type": "concept", "title": "Orientalism"}, {"id": "3602b6ff-f5f9-4dde-b19b-befc48d301cc", "type": "concept", "title": "Subaltern"}, {"id": "8b83f66c-3e26-4f99-be2b-28454f2576ed", "type": "concept", "title": "Mimicry"}, {"id": "7fe7b3e5-a4ee-42a6-9692-e8ce448b647e", "type": "concept", "title": "Hybridity"}, {"id": "3fb2cd19-ff8a-4faa-a81a-f54959f90980", "type": "concept", "title": "Othering"}, {"id": "899738df-7c4a-4b66-addc-262a4618a205", "type": "concept", "title": "Discourse"}], "description": "This subtopic introduces critiques of representation, orientalism, subalternity, and knowledge/power."}, {"id": "fd9e581b-2b27-48e6-86ae-2cd4c22345de", "type": "subtopic", "title": "Decolonial and Indigenous methodologies", "children": [{"id": "03da34ae-302b-43b3-8e88-7260edf9a895", "type": "concept", "title": "Decolonization"}, {"id": "bea7d038-c03e-4773-a7f9-96fcdbaa95fb", "type": "concept", "title": "Indigenous sovereignty"}, {"id": "b1562a39-4920-4ec4-8d85-d52af99eac11", "type": "concept", "title": "Repatriation"}, {"id": "496c8e31-d3c0-4bce-8f19-1a186ab5ef3a", "type": "concept", "title": "Refusal"}, {"id": "ca782d5f-eb75-4700-86f6-0905fc6b0345", "type": "concept", "title": "Collaborative research"}, {"id": "22bf9d5b-6a55-44a2-9a2d-f6c6026b49a0", "type": "concept", "title": "Data sovereignty"}], "description": "Students consider research ethics, sovereignty, repatriation, refusal, collaboration, and community accountability."}]}, {"id": "2c0fa83d-721b-43f6-b534-079ea6be1658", "type": "topic", "title": "Science, Technology, Materiality, and Infrastructure", "description": "Explores how objects, technologies, laboratories, infrastructures, and expert systems participate in social life.", "children": [{"id": "ab96655e-b3bb-427e-96f0-73221fa5e212", "type": "subtopic", "title": "Material culture and thing theory", "children": [{"id": "c03b178c-ae44-4286-85d4-18348173541f", "type": "concept", "title": "Object biography"}, {"id": "9bf2e765-fc33-467f-9e7d-fda5cf314a6e", "type": "concept", "title": "Materiality"}, {"id": "57574e84-017d-457a-aa85-0cc16c2c2499", "type": "concept", "title": "Agency of things"}, {"id": "9dfb6176-9bb3-441f-882e-ac2ebc2405f8", "type": "concept", "title": "Value"}, {"id": "61b8f429-9c97-432d-956d-b8dfd01c14c1", "type": "concept", "title": "Consumption"}, {"id": "e3ff623c-17c4-4c31-9302-8176e0ed55a9", "type": "concept", "title": "Collections"}], "description": "Students learn to analyze objects as active parts of social relations, memory, value, and identity."}, {"id": "9e09e27c-840d-4484-be43-5c34368722e4", "type": "subtopic", "title": "Science and technology studies", "children": [{"id": "fd16b41e-78ec-40ba-865f-f71056d224ce", "type": "concept", "title": "Latour"}, {"id": "0631a83a-fcc2-401a-bf70-bc230e31bbf0", "type": "concept", "title": "Laboratory studies"}, {"id": "2e547697-c54d-401f-95d4-a3c108de67e3", "type": "concept", "title": "Actor-network theory"}, {"id": "ccfba094-a4c9-4148-a03f-6afd7f75c8fc", "type": "concept", "title": "Black box"}, {"id": "37a5e784-fef9-4d00-96f6-4b5d00b8bc59", "type": "concept", "title": "Inscription"}, {"id": "8e83b803-30c4-4c04-82af-f9b2e592215c", "type": "concept", "title": "Expertise"}], "description": "This subtopic tracks how facts, instruments, laboratories, experts, and publics are socially produced."}, {"id": "5b56c8cc-e89d-4ee3-8782-d5b4bf8fe725", "type": "subtopic", "title": "Infrastructure and technopolitics", "children": [{"id": "1d10d5ff-be5b-40f8-87b3-aa4f951fe118", "type": "concept", "title": "Infrastructure"}, {"id": "23f90cf6-3fde-4a00-afdf-08de38e8cf6f", "type": "concept", "title": "Standards"}, {"id": "eef07aa7-da39-4c6e-b63f-fc2372ea3edb", "type": "concept", "title": "Maintenance"}, {"id": "17bac426-9b2a-4ae0-81e2-ed8923e87d17", "type": "concept", "title": "Breakdown"}, {"id": "b3900ecd-7239-4c75-a07c-7c0bf0a1898c", "type": "concept", "title": "Technopolitics"}, {"id": "7e7ee7cc-d5ae-49e0-8505-8a2a1fb50591", "type": "concept", "title": "Platformization"}], "description": "Students examine roads, grids, platforms, standards, and systems as materialized politics."}]}, {"id": "e487a8e5-1443-4d45-aed6-ad91a326e8de", "type": "topic", "title": "Ontological, Multispecies, and Environmental Turns", "description": "Introduces recent debates about worlds, nonhuman life, ecology, climate, animals, spirits, landscapes, and more-than-human relations.", "children": [{"id": "3233ef94-b2f4-4d2d-801e-974d0473feb6", "type": "subtopic", "title": "Ontological turn", "children": [{"id": "801c3e36-f17a-4e52-963e-a22750071b37", "type": "concept", "title": "Ontology"}, {"id": "4cdd0dc4-59bb-4e71-a4b9-10a9c6b6f82e", "type": "concept", "title": "Perspectivism"}, {"id": "bbd04bb5-bfa1-4396-b1d4-ceb59ce24308", "type": "concept", "title": "Multinaturalism"}, {"id": "e3f0882f-7189-4813-9ede-95adfde3ce08", "type": "concept", "title": "Worlding"}, {"id": "ee90434f-7ed9-4cc7-9317-2c122bef17b2", "type": "concept", "title": "Translation"}, {"id": "6d4c8990-df3c-4a33-863a-527b8c6076bd", "type": "concept", "title": "Equivocation"}], "description": "Students explore debates about whether anthropology compares cultures or worlds, and what is at stake in that claim."}, {"id": "c451da13-176e-42c8-9340-37f841944cab", "type": "subtopic", "title": "Multispecies ethnography", "children": [{"id": "47dc29d2-37cd-47a9-a1ab-fcc0528e4b5c", "type": "concept", "title": "Companion species"}, {"id": "1e4d1c15-c54f-4ae3-b005-4848f7d77dc3", "type": "concept", "title": "More-than-human"}, {"id": "4350c868-0485-4bb1-89a2-9c00b0da0ba0", "type": "concept", "title": "Symbiosis"}, {"id": "04006fa2-ac74-4da9-8468-aea033276d19", "type": "concept", "title": "Domestication"}, {"id": "2b27c709-dd4c-463d-947d-f0751ad8e7e9", "type": "concept", "title": "Zoonosis"}, {"id": "eb5040a1-46a0-4f7b-9f72-f642d80c07ae", "type": "concept", "title": "Extinction"}], "description": "This subtopic expands ethnographic attention to animals, plants, microbes, environments, and interspecies dependencies."}, {"id": "30b27f0b-a282-4efc-b570-1f15c4a80690", "type": "subtopic", "title": "Anthropocene and climate anthropology", "children": [{"id": "74a1132b-0701-4be5-b6bf-3324978aabd0", "type": "concept", "title": "Anthropocene"}, {"id": "c6da3da1-5d71-4407-80ef-bebc5733dfa6", "type": "concept", "title": "Capitalocene"}, {"id": "63a9bef8-582c-4692-bec9-109db3757f9f", "type": "concept", "title": "Climate justice"}, {"id": "da6471d6-afee-4609-ad77-e4dfeaf6a579", "type": "concept", "title": "Toxicity"}, {"id": "0f89cf2f-9fa0-422a-99da-cc584be3e649", "type": "concept", "title": "Ruins"}, {"id": "559279ad-5f49-415b-beda-7a1fb28ac3d5", "type": "concept", "title": "Adaptation"}], "description": "Students connect theory to planetary crisis, extraction, environmental justice, and uneven vulnerability."}]}, {"id": "e59c1ad3-1137-4d28-856a-288b7c5da672", "type": "topic", "title": "Language, Semiotics, and Discourse", "description": "Shows how language and signs mediate identity, authority, ideology, social interaction, and cultural reproduction.", "children": [{"id": "e390ddd4-36eb-43c3-af6f-7f0d1d7e3ef9", "type": "subtopic", "title": "Linguistic relativity and language ideology", "children": [{"id": "550b93c5-16e7-4578-952f-92fb2fd086eb", "type": "concept", "title": "Sapir-Whorf"}, {"id": "a3a36620-a6eb-41dd-bff6-25593554751d", "type": "concept", "title": "Language ideology"}, {"id": "b50ab0ae-7c3a-4c20-bd29-61d00087632f", "type": "concept", "title": "Metapragmatics"}, {"id": "279eba19-7bd9-46c1-98e9-270915563407", "type": "concept", "title": "Indexicality"}, {"id": "92e4aa2c-05db-4bf6-b293-69934dc1cd9c", "type": "concept", "title": "Register"}, {"id": "16183ffd-fdfd-4bc1-8988-3643b6c44995", "type": "concept", "title": "Standard language"}], "description": "Students learn how language categories and beliefs about language shape social worlds."}, {"id": "473c6c64-5688-44d9-8d70-795ba879eb33", "type": "subtopic", "title": "Semiotics and sign processes", "children": [{"id": "b3fdbf24-99af-4249-8b73-c0e938a92d3a", "type": "concept", "title": "Peirce"}, {"id": "e0a010c4-2e8e-45dc-9639-3e28a7656e25", "type": "concept", "title": "Icon"}, {"id": "9d038474-fdbd-459e-8f5d-cdbc4568c02f", "type": "concept", "title": "Index"}, {"id": "06b2f46d-f355-4a6d-a320-982720c2d2b8", "type": "concept", "title": "Symbol"}, {"id": "32116851-1027-4b7b-b03f-444217b4d251", "type": "concept", "title": "Semiotic ideology"}, {"id": "736127b0-a9a0-4683-b65d-3f58533f1a85", "type": "concept", "title": "Enregisterment"}], "description": "This subtopic gives students tools for analyzing signs, icons, indexes, symbols, and meaning-making."}, {"id": "0eb1c313-8213-4653-836b-011a6370592a", "type": "subtopic", "title": "Discourse, power, and subject formation", "children": [{"id": "9d124150-b3e6-4bbf-92c3-d924d930474d", "type": "concept", "title": "Foucault"}, {"id": "abc4aebf-7879-4b8e-918f-13e7abb73818", "type": "concept", "title": "Discourse"}, {"id": "e2be50b1-ad28-406a-92e0-b6e489d50100", "type": "concept", "title": "Subjectivity"}, {"id": "d94d74fb-cd77-4690-b587-0dcc4b7b96fa", "type": "concept", "title": "Governmentality"}, {"id": "c58c7e30-ba00-442f-8632-d961b231fe19", "type": "concept", "title": "Normativity"}, {"id": "29eb2105-1347-479d-8d46-54b66fe63103", "type": "concept", "title": "Knowledge/power"}], "description": "Students examine how discourse creates categories, identities, norms, and governable subjects."}]}, {"id": "fcaa6395-0bbc-4bd0-8875-6d68d5566705", "type": "topic", "title": "Ethnographic Authority, Reflexivity, and Writing Culture", "description": "Examines the crisis of representation and the craft of writing ethnography ethically, analytically, and reflexively.", "children": [{"id": "ae923557-3faa-4d82-ab16-5cda6405781a", "type": "subtopic", "title": "Representation and voice", "children": [{"id": "a1f55b50-5091-4340-9299-b725b19fe4bf", "type": "concept", "title": "Ethnographic authority"}, {"id": "c5a15ee1-c0a3-471c-8fe6-46b990fb59f8", "type": "concept", "title": "Voice"}, {"id": "0e04cf9a-1bb1-45b9-9d24-60a5b0d4b46c", "type": "concept", "title": "Polyphony"}, {"id": "8dce85bd-d5bf-4088-a6a9-2eec0d4301b5", "type": "concept", "title": "Quotation"}, {"id": "7cfc83a1-f092-4e64-90b0-aea40c8d9639", "type": "concept", "title": "Scene"}, {"id": "1d3bf59d-0ec6-4cb8-8974-52155b614dd5", "type": "concept", "title": "Narrative stance"}], "description": "Students learn how ethnographic writing constructs authority and how choices about voice shape readers' understanding."}, {"id": "25873961-983e-4b43-92dd-b7c372a9b87c", "type": "subtopic", "title": "Reflexivity and positionality", "children": [{"id": "b3f8677c-5aef-485a-bc1b-1e01dcbb118a", "type": "concept", "title": "Positionality"}, {"id": "ccba69f0-dfdb-4c96-b5c2-b19d1be852aa", "type": "concept", "title": "Reflexivity"}, {"id": "40a3629d-a18a-4d84-9085-5224db9a83dc", "type": "concept", "title": "Field relations"}, {"id": "d83f5a47-7e24-496a-a005-3594ef2cd54a", "type": "concept", "title": "Power"}, {"id": "3f851cc1-74d7-482b-893f-08856c57aed6", "type": "concept", "title": "Reciprocity"}, {"id": "4b897bc2-3aad-4b70-9443-27c82d7383c2", "type": "concept", "title": "Accountability"}], "description": "This subtopic teaches students to analyze the researcher's role without making the work only about the researcher."}, {"id": "df6141b6-8cc2-40d7-8633-9510a92c2eec", "type": "subtopic", "title": "Experimental and collaborative writing", "children": [{"id": "ca7246af-b9af-4bf1-ac05-dddd9a9461e9", "type": "concept", "title": "Co-authorship"}, {"id": "e2de7ef7-d36e-4df0-955b-1bd7f8786c39", "type": "concept", "title": "Collaborative ethnography"}, {"id": "8ff1d860-a3d1-4bd4-a122-5c05159f768b", "type": "concept", "title": "Autoethnography"}, {"id": "fbc07e07-69bd-4e69-992a-a4a5a6144418", "type": "concept", "title": "Multimodal ethnography"}, {"id": "143f1f31-25bf-4c4c-9cc7-0caf15e240d9", "type": "concept", "title": "Public writing"}, {"id": "34047d00-2415-4939-95a7-b21e815175a9", "type": "concept", "title": "Peer review"}], "description": "Students consider genres that include dialogue, co-authorship, multimodality, community review, and public scholarship."}]}, {"id": "cd5fb8cb-5662-4c98-ba5b-449db8342bed", "type": "topic", "title": "Globalization, Mobility, Neoliberalism, and the State", "description": "Links contemporary anthropological theory to migration, borders, markets, bureaucracy, development, security, and state power.", "children": [{"id": "d83f3079-fea3-4366-88df-1a0318390fa2", "type": "subtopic", "title": "Mobility and transnationalism", "children": [{"id": "60150262-457f-4918-8c4f-467b36b68f8c", "type": "concept", "title": "Diaspora"}, {"id": "e77329ed-bc02-432f-adae-5c3dc3904775", "type": "concept", "title": "Transnationalism"}, {"id": "acdb5a63-4a41-4696-821d-b8958e8a2c1b", "type": "concept", "title": "Remittances"}, {"id": "a2429207-a430-428f-841f-da139ead872c", "type": "concept", "title": "Border regimes"}, {"id": "2cebc3d1-38ed-4190-b1f5-ccaa2f400a30", "type": "concept", "title": "Mobility"}, {"id": "3fffbdfa-2f81-4341-af89-5f5f2a40c5e1", "type": "concept", "title": "Circulation"}], "description": "Students analyze movement of people, money, images, ideas, commodities, and obligations across borders."}, {"id": "1bf31e3e-7d0f-421c-b50d-60b9848e3099", "type": "subtopic", "title": "Neoliberalism and governance", "children": [{"id": "65f6e853-6e86-404d-a56a-ccee1e02d865", "type": "concept", "title": "Neoliberalism"}, {"id": "34c6eed8-2640-4925-8661-6c66c1d16227", "type": "concept", "title": "Audit culture"}, {"id": "93656aa8-0d31-4def-af1e-511f8effacbd", "type": "concept", "title": "Precarity"}, {"id": "507571cd-391e-4c26-9e6a-71a6fafedad8", "type": "concept", "title": "Entrepreneurial self"}, {"id": "6dc43390-f203-4b83-8c78-574f3d27ea98", "type": "concept", "title": "Structural adjustment"}, {"id": "e035da1f-835c-451a-bce3-cc71859c608a", "type": "concept", "title": "NGOs"}], "description": "This subtopic explains how market logics reshape subjectivity, welfare, labor, risk, and responsibility."}, {"id": "08672ae7-4d55-4538-ab74-5cf5b35c838c", "type": "subtopic", "title": "State, bureaucracy, and 